/**
 * PROTOTYPE - builds docs/design/overview-directions/vendor/office-kit.js: the
 * desktop app's 3D Office kit (apps/desktop/src/renderer/office) and three.js,
 * bundled with office-kit-entry.ts into one minified classic script that
 * defines the globals `THREE` and `OfficeKit`. A classic script, not a
 * module, so a drawing works over http and from file:// alike.
 *
 * To rebuild after the kit changes (Bun is the version in .bun-version):
 *
 *   # once: three.js at the version apps/desktop/package.json pins, outside the repo
 *   mkdir -p /tmp/ovtools/kitbuild && cd /tmp/ovtools/kitbuild && bun add three@0.186.1
 *
 *   # from the repository root
 *   bun docs/design/overview-directions/vendor/build-office-kit.ts
 *
 * Options:
 *   --deps <dir>   the folder whose node_modules holds three (default /tmp/ovtools/kitbuild)
 *   --repo <dir>   the repository root (default: four folders up from this script)
 *
 * The app's code is written for Vite; one Bun plugin covers what Vite does
 * for it:
 *   - `three` and `three/examples/jsm/...` resolve to the three.js in --deps;
 *   - `import text from "./file.css?raw"` becomes the file's text;
 *   - `@hercule/*` packages resolve to an empty module, because the office
 *     kit imports only types from them. A value import from one fails the
 *     build with "No matching export", rather than going missing silently.
 */
import { existsSync } from "node:fs";
import { dirname, join, resolve } from "node:path";
import type { BunPlugin } from "bun";

/** Returns the value of `--name <value>` on the command line, or `fallback`. */
function readOption(name: string, fallback: string): string {
  const index = process.argv.indexOf(`--${name}`);
  const value = index < 0 ? undefined : process.argv[index + 1];
  return value ?? fallback;
}

const repo = resolve(readOption("repo", join(import.meta.dir, "../../../..")));
const deps = resolve(readOption("deps", "/tmp/ovtools/kitbuild"));
const vendor = join(repo, "docs/design/overview-directions/vendor");
const entry = join(vendor, "office-kit-entry.ts");
const output = join(vendor, "office-kit.js");
const threeRoot = join(deps, "node_modules/three");

if (!existsSync(join(repo, "apps/desktop/package.json"))) {
  throw new Error(`${repo} is not the Hercule repository. Pass its root with --repo <dir>.`);
}
const desktop = await Bun.file(join(repo, "apps/desktop/package.json")).json();
const pinned: string = desktop.dependencies?.three ?? desktop.devDependencies?.three;
if (!existsSync(join(threeRoot, "package.json"))) {
  throw new Error(
    `No three.js in ${deps}/node_modules. Install the version the app pins:\n  mkdir -p ${deps} && cd ${deps} && bun add three@${pinned}`,
  );
}
const installed = (await Bun.file(join(threeRoot, "package.json")).json()).version;
if (installed !== pinned) {
  throw new Error(
    `${deps} has three ${installed}, but apps/desktop pins ${pinned}. Run: cd ${deps} && bun add three@${pinned}`,
  );
}

const vitePlugin: BunPlugin = {
  name: "office-kit-vite-bits",
  setup(build) {
    build.onResolve({ filter: /^three$/ }, () => ({ path: join(threeRoot, "build/three.module.js") }));
    build.onResolve({ filter: /^three\/examples\/jsm\// }, (args) => ({
      path: join(threeRoot, args.path.slice("three/".length)),
    }));
    build.onResolve({ filter: /^@hercule\// }, (args) => ({ path: args.path, namespace: "types-only" }));
    build.onLoad({ filter: /.*/, namespace: "types-only" }, () => ({
      contents: "export {};",
      loader: "js",
    }));
    build.onResolve({ filter: /\?raw$/ }, (args) => ({
      path: resolve(dirname(args.importer), args.path.replace(/\?raw$/, "")),
      namespace: "raw",
    }));
    build.onLoad({ filter: /.*/, namespace: "raw" }, async (args) => ({
      contents: `export default ${JSON.stringify(await Bun.file(args.path).text())};`,
      loader: "js",
    }));
  },
};

const result = await Bun.build({
  entrypoints: [entry],
  format: "iife",
  target: "browser",
  minify: true,
  plugins: [vitePlugin],
});
if (!result.success) {
  for (const log of result.logs) console.error(log);
  throw new Error("The office kit did not build.");
}

const commit = Bun.spawnSync(["git", "-C", repo, "rev-parse", "--short", "HEAD"]).stdout.toString().trim();
const banner =
  `/* office-kit.js - GENERATED by build-office-kit.ts; do not edit, rebuild instead (see OFFICE-KIT.md).\n` +
  `   The desktop app's 3D Office kit (apps/desktop/src/renderer/office at ${commit}) and three.js ${installed}.\n` +
  `   Globals: THREE, OfficeKit. three.js is MIT licensed, copyright 2010-2026 three.js authors. */\n`;
const code = banner + (await result.outputs[0]!.text());
await Bun.write(output, code);

const bytes = Buffer.byteLength(code);
const gzipped = Bun.gzipSync(Buffer.from(code)).byteLength;
console.log(
  `Wrote ${output}: ${(bytes / 1024).toFixed(0)} KiB, ${(gzipped / 1024).toFixed(0)} KiB gzipped.`,
);
